package local.pocketchat;
import java.util.*;import java.util.function.*;import org.json.*;import org.mozilla.geckoview.*;
public class ContentPermissionDecisionsHost {
 static JSONArray checks=new JSONArray();static final String ORIGIN="https://owned.test";
 static void check(String name,boolean pass){checks.put(J.obj("name",name,"pass",pass));if(!pass)throw new AssertionError(name);}
 static final class Run {final ChatSession owner;final GeckoWebView web;final GeckoContentPermissions gate;Run(){owner=new ChatSession();ChatSession.instance=owner;web=new GeckoWebView(owner);owner.web=web;gate=new GeckoContentPermissions(web);}GeckoResult<Integer> ask(int type){return gate.request(web.current,permission(type,0));}GeckoSession.PermissionDelegate.ContentPermission permission(int type,int value){return p(ORIGIN,ORIGIN,"context-a",false,type,value);}StorageController store(){return web.runtime.storage;}void answer(int value){store().last.complete(Arrays.asList(permission(1,value)));}}
 static GeckoSession.PermissionDelegate.ContentPermission p(String origin,String third,String context,boolean privateMode,int type,int value){return new GeckoSession.PermissionDelegate.ContentPermission(origin,third,context,privateMode,type,value);}
 static List<GeckoSession.PermissionDelegate.ContentPermission> stored(int type,int value){return Arrays.asList(p(ORIGIN,null,"context-a",false,type,value));}
 static void result(String name,GeckoResult<Integer> r,int expected){check(name,r.done&&Objects.equals(r.value,expected)&&r.completions==1&&r.value!=SitePermissions.ALLOW);}
 static void stale(String name,Consumer<Run> mutation){Run r=new Run();StorageController original=r.store();GeckoResult<Integer> value=r.ask(1);mutation.accept(r);original.last.complete(stored(1,2));result("Stale "+name+" cannot supply a current permission decision",value,SitePermissions.DENY);check("Stale "+name+" does not write permission storage",StorageController.writes==0);}
 public static void main(String[] args)throws Exception{
  Run r=new Run();GeckoResult<Integer> value=r.ask(1);check("A normal current native request reaches one SDK store query",r.store().reads==1&&!value.done);check("The exact stored query uses owned origin context and private namespace",r.store().origin.equals(ORIGIN)&&r.store().context.equals("context-a")&&!r.store().privateMode);check("Native lookup is confined to the existing owner handler",r.store().last.handler==r.owner.handler);r.store().last.complete(Collections.emptyList());result("An absent stored record preserves native PROMPT without granting",value,3);
  for(int type:new int[]{0,1,3,9,10})for(int stored:new int[]{1,2,3}){r=new Run();value=r.ask(type);r.store().last.complete(stored(type,stored));result("Supported type "+type+" stored value "+stored+" never grants",value,stored==2?2:3);}
  r=new Run();value=r.ask(1);r.store().last.complete(Arrays.asList(p("https://other.test",null,"context-a",false,1,2)));result("Another origin's denial is never borrowed",value,3);
  r=new Run();value=r.ask(1);r.store().last.complete(Arrays.asList(p(ORIGIN,null,"context-b",false,1,2)));result("Another context's denial is never borrowed",value,3);
  r=new Run();value=r.ask(1);r.store().last.complete(Arrays.asList(p(ORIGIN,null,"context-a",true,1,2)));result("Private namespace denial is never borrowed",value,3);
  r=new Run();value=r.ask(1);r.store().last.complete(stored(0,2));result("Another type's denial is never borrowed",value,3);
  r=new Run();value=r.ask(1);r.store().last.complete(Arrays.asList(p(ORIGIN,"https://third.test","context-a",false,1,2)));result("An unexpected third-party ordinary stored record fails closed",value,2);
  r=new Run();value=r.ask(1);r.store().last.complete(Arrays.asList(p(ORIGIN,"https://third.test","context-a",false,8,2)));result("A separate special storage-access record cannot supply an ordinary permission",value,3);
  r=new Run();value=r.ask(1);r.store().last.complete(Arrays.asList(p(ORIGIN,"bogus","context-a",false,1,2)));result("An invalid normalized third-party stored origin fails closed",value,2);
  for(String bad:new String[]{"null-list","null-record","bad-value","unknown-type","duplicate","overflow"}){r=new Run();value=r.ask(1);List<GeckoSession.PermissionDelegate.ContentPermission> rows=null;
   if(bad.equals("null-record"))rows=Arrays.asList((GeckoSession.PermissionDelegate.ContentPermission)null);
   if(bad.equals("bad-value"))rows=stored(1,0);if(bad.equals("unknown-type"))rows=stored(99,2);if(bad.equals("duplicate"))rows=Arrays.asList(stored(1,2).get(0),stored(1,3).get(0));if(bad.equals("overflow"))rows=Collections.nCopies(129,stored(1,2).get(0));r.store().last.complete(rows);result("Invalid "+bad+" fails closed",value,2);}
  for(int type:new int[]{2,4,5,6,7,8}){r=new Run();value=r.ask(type);result("Existing special type "+type+" retains original PROMPT policy",value,3);check("Special type "+type+" introduces no stored lookup",r.store().reads==0);}
  for(int type:new int[]{-1,11,999}){r=new Run();value=r.ask(type);result("Unknown type "+type+" is denied",value,2);check("Unknown type "+type+" never queries native storage",r.store().reads==0);}
  for(int raw:new int[]{-1,4}){r=new Run();value=r.gate.request(r.web.current,r.permission(1,raw));result("Invalid live native value "+raw+" is denied",value,2);check("Invalid live value "+raw+" never queries storage",r.store().reads==0);}
  for(String bad:new String[]{"origin","context","private","session","null","oversize-principal"}){r=new Run();GeckoSession session=r.web.current;GeckoSession.PermissionDelegate.ContentPermission permission=r.permission(1,0);
   if(bad.equals("origin"))permission=p("https://foreign.test",ORIGIN,"context-a",false,1,0);if(bad.equals("context"))permission=p(ORIGIN,ORIGIN,"context-b",false,1,0);if(bad.equals("private"))permission=p(ORIGIN,ORIGIN,"context-a",true,1,0);if(bad.equals("session"))session=new GeckoSession();if(bad.equals("null"))permission=null;if(bad.equals("oversize-principal"))permission=p(ORIGIN,String.join("",Collections.nCopies(2049,"x")),"context-a",false,1,0);
   value=r.gate.request(session,permission);result("Invalid request "+bad+" is denied",value,2);check("Invalid request "+bad+" never queries storage",r.store().reads==0);}
  r=new Run();value=r.ask(1);GeckoResult<List<GeckoSession.PermissionDelegate.ContentPermission>> firstRead=r.store().last;GeckoResult<Integer> concurrent=r.ask(1);result("A concurrent permission request fails closed immediately",concurrent,2);check("Only one native lookup can be in flight",r.store().reads==1);firstRead.complete(Collections.emptyList());result("The first in-flight request retains its own result",value,3);
  r=new Run();value=r.ask(1);firstRead=r.store().last;check("Lookup deadline is exactly the existing three-second budget",r.owner.handler.delays.equals(Arrays.asList(3000L)));r.owner.handler.fire();result("A missing lookup response is denied at the bounded deadline",value,2);GeckoResult<Integer> blockedAfterTimeout=r.ask(1);result("An uncancellable native lookup keeps its one actual slot after timeout",blockedAfterTimeout,2);check("Timeout cannot start a concurrent native lookup",r.store().reads==1);firstRead.complete(Collections.emptyList());result("A late default response cannot complete or replace a timeout",value,2);check("Timeout releases the handler task",r.owner.handler.tasks.isEmpty());value=r.ask(1);r.store().last.complete(Collections.emptyList());result("Native callback releases the actual lookup slot for a new current request",value,3);check("Only the new request after native settlement issues a second query",r.store().reads==2);
  r=new Run();value=r.ask(1);r.store().last.completeExceptionally(new IllegalStateException("private native error"));result("Native lookup failure is denied without escaping",value,2);
  r=new Run();r.store().throwAfterDispatch=true;value=r.ask(1);result("Uncertain native dispatch failure is denied",value,2);result("Uncertain native dispatch retains its one physical slot",r.ask(1),2);check("A dispatch exception cannot create an unbounded concurrent native query",r.store().reads==1);
  stale("runtime",x->x.web.runtime=new GeckoRuntime());stale("session",x->x.web.current=new GeckoSession());stale("port",x->x.web.ports.put(x.web.current,new Object()));stale("same-URL load",x->x.web.appearanceLoads.put(x.web.current,2L));stale("navigation",x->x.owner.navigationEpoch++);stale("document",x->x.owner.lastDocumentId="replacement-document");stale("location",x->x.web.locations.put(x.web.current,ORIGIN+"/new"));stale("identity policy",x->x.web.identityPolicyRevision++);stale("applied configuration",x->x.owner.applied++);stale("connection",x->x.owner.connectionEpoch++);stale("deleted owner",x->x.owner.deleted=true);stale("disabled browser",x->x.web.enabled=false);stale("destroyed browser",x->x.web.destroyed=true);stale("closed SDK session",x->x.web.current.open=false);stale("pending native load",x->x.web.pendingLoads.add(x.web.current));stale("crashed SDK session",x->x.web.crashed.add(x.web.current));stale("navigating owner",x->x.owner.navigating=true);stale("retired singleton",x->ChatSession.instance=new ChatSession());stale("retired browser",x->x.owner.web=new GeckoWebView(x.owner));stale("catalog UUID",x->ProfileCatalog.id="00000000-0000-0000-0000-000000000099");stale("catalog generation",x->ProfileCatalog.generation++);stale("catalog deleting",x->ProfileCatalog.unavailable=true);stale("context settings",x->x.web.current.settings.context="context-b");stale("private settings",x->x.web.current.settings.privateMode=true);
  r=new Run();for(int i=0;i<32;i++){value=r.ask(1);r.store().last.complete(Collections.emptyList());result("Bounded normal lookup "+i+" preserves default",value,3);}value=r.ask(1);result("The per-document lookup count is bounded",value,2);check("The lookup limit issues only 32 native reads",r.store().reads==32);r.web.appearanceLoads.put(r.web.current,2L);value=r.ask(1);r.store().last.complete(Collections.emptyList());result("A genuinely new native load has a fresh bounded lookup budget",value,3);
  r=new Run();value=r.ask(1);firstRead=r.store().last;r.gate.close();result("Closing the browser settles its only pending request as denied",value,2);firstRead.complete(stored(1,2));result("Closed request cannot be completed twice by a late native read",value,2);result("Closed gate never issues another lookup",r.ask(1),2);check("Close releases native lookup timeout and storage writes remain absent",r.owner.handler.tasks.isEmpty()&&r.store().reads==1&&StorageController.writes==0);
  System.out.println(J.obj("status","passed","checks",checks.length(),"results",checks,"actualAndroidExecution",false,"actualGeckoExecution",false,"actualSdkApiCompile",false,"physicalPhoneAcceptance",false));
 }
}
class ChatSession {static ChatSession instance;static ChatSession peek(){return instance;}Object context=new Object();GeckoWebView web;final FakeHandler handler=new FakeHandler();boolean deleted,navigating;final int environmentGeneration=4;final String environmentId="00000000-0000-0000-0000-000000000001";long navigationEpoch=3,connectionEpoch=5,applied=7;String lastDocumentId="current-document";ChatSession(){ProfileCatalog.id=environmentId;ProfileCatalog.generation=environmentGeneration;ProfileCatalog.unavailable=false;}long identityAuditAppliedRevision(){return applied;}}
class FakeHandler {List<Runnable> tasks=new ArrayList<>();List<Long> delays=new ArrayList<>();void postDelayed(Runnable r,long n){tasks.add(r);delays.add(n);}void removeCallbacks(Runnable r){tasks.remove(r);}void fire(){for(Runnable r:new ArrayList<>(tasks))r.run();}}
class GeckoWebView {final ChatSession owner;GeckoRuntime runtime=new GeckoRuntime();GeckoSession current=new GeckoSession();boolean destroyed,enabled=true,ready=true,failed;long identityPolicyRevision=9;final Map<GeckoSession,String> locations=new IdentityHashMap<>();final Map<GeckoSession,Object> ports=new IdentityHashMap<>();final Map<GeckoSession,Long> appearanceLoads=new IdentityHashMap<>();final Set<GeckoSession> crashed=new HashSet<>(),pendingLoads=new HashSet<>(),usable=new HashSet<>();GeckoWebView(ChatSession s){owner=s;locations.put(current,ContentPermissionDecisionsHost.ORIGIN+"/page");ports.put(current,new Object());appearanceLoads.put(current,1L);usable.add(current);}/* VISIBLE */}
class Profiles {static int slot(Object c){return 2;}}
class EnvironmentSpec {static class Identity {final String environmentId;final int generation;Identity(String id,int gen){environmentId=id;generation=gen;}}}
class ProfileCatalog {static String id;static int generation;static boolean unavailable;static ProfileCatalog get(Object context){return new ProfileCatalog();}EnvironmentSpec.Identity identity(int slot)throws java.io.IOException{if(unavailable)throw new java.io.IOException("unavailable");return new EnvironmentSpec.Identity(id,generation);}}
